import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { Observable } from 'rxjs/internal/Observable';
import { ReadingMouseData } from '../models/ReadingMouseData';

@Injectable({
  providedIn: 'root'
})
export class VisualSearchDataTransferService {
  private apiUrl = 'http://localhost:4000/visualSearch/sendData';

  constructor(private http: HttpClient) {}

  sendMouseData(iteration: number, isCorrect: boolean,isControl: boolean, reactionTime: number, events: ReadingMouseData[], sessionId: string ): Observable<any> {
    const payload = {
      iteration,
      isCorrect,
      isControl,
      reactionTime,
      events,
      sessionId
    };

    return this.http.post(this.apiUrl, payload);
  }
}
